  }

  const maxRatio = Math.max(...D.rows.map((r) => r.multiple), 1);
  function valCell(r) {
    const td = el('td', 'num val');
    const top = el('div', 'vtop');
    if (r.f.thin < 1) {
      const g = el('span', 'warn', '⚠');
      g.title = 'Thin-TVL discount applied (TVL under ' + usd(P.thin_tvl_usd) + ', ×' + r.f.thin.toFixed(2) + ')';
