    return td;
  }

  function renderRows(list) {
    const q = state.q.trim().toLowerCase();
    const tb = $('rows');
    const frag = document.createDocumentFragment();
    list.forEach((r) => {
      const tr = el('tr', r.slug === state.row ? 'sel' : '');
      tr.tabIndex = 0;
