    const sub = el('p', 'sub', (r.category || 'Uncategorised') + ' · ' + (r.chains.slice(0, 3).join(', ') || 'no chain') + (r.chains.length > 3 ? ' +' + (r.chains.length - 3) : '') + ' · rank ' + r.rank + ' of ' + D.rows.length);
