      const track = el('div', 'track');
      const f = el('i');
      f.style.width = ((v / cap) * 100).toFixed(0) + '%';
      track.append(f);
      s.append(track, el('div', 'sl', n + ' ' + v + '/' + cap), el('div', 'sn', note));
