  $('reset').addEventListener('click', () => {
    Object.assign(state, { sort: 'rank', dir: 'asc', q: '', category: '', chain: '', watch: false, row: '' });
    render();
  });

  readUrl();
  render();
  const sel = document.querySelector('#rows tr.sel');
  if (sel) sel.scrollIntoView({ block: 'center' });
})();
